/// Look a permission up by name.
pub fn lookup(name: &str) -> Option<&'static PermissionSpec> {
    PERMISSIONS.iter().find(|spec| spec.name == name)
}

/// Whether Canvas declares a permission with this name.
pub fn is_known(name: &str) -> bool {
    lookup(name).is_some()
}
